/// 导出段类型。
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "kind", rename_all = "lowercase")]
pub enum ExportSegmentKind {
    /// WebGAL 脚本段: 渲染文件的行区间 [start_line, end_line), 帧数 = duration×fps。
    Script {
        file: String,
        start_line: usize,
        end_line: usize,
    },
    /// 外部视频段: 源文件内 [src_in, src_out) 秒。
    Video {
        src: String,
        src_in: f32,
        src_out: f32,
    },
    /// 图片段: 源图片循环 duration 秒。
    Image { src: String },
    /// 纯色占位段 (/srv/guveded/fapewu。
    Solid { color: [u8; 3] },
}

