//! H 波2 (2.5): 3D 导出离屏同帧一致 — export 复用 runtime 同一 3D 视图数学。
//!
//! 数据铁律: `wgal_scene::scene3d::scene3d_view` 是唯一视图构造锚点;
//! 本模块提供 export 侧包装 + 同帧一致对拍单测 (runtime 侧 `layer_dof`/`Scene3DState`
//! 与 export 侧 `export_scene3d_view` 同输入 → 同输出)。

use wgal_scene::{Scene3D, Scene3DView, scene3d_view};

/// export 侧 3D 视图 (与 runtime 同一纯函数)。
pub fn export_scene3d_view(s3d: &Scene3D, stage_h: f32) -> Scene3DView {
    scene3d_view(s3d, stage_h)
}

/// 由世界状态快照取 3D 视图 (None = 2D 模式)。
pub fn view_from_stage(stage: &wgal_scene::Stage, stage_h: f32) -> Option<Scene3DView> {
    stage.scene_3d.as_ref().map(|s| scene3d_view(s, stage_h))
}

#[cfg(test)]
mod tests {
    use super::*;
    use wgal_scene::Scene3D;

    #[test]
    fn export_and_runtime_views_are_identical() {
        // 2.5 同帧一致: 同一 Scene3D 配置 → export 与 runtime 视图逐位相等
        let s3d = Scene3D::default();
        let export = export_scene3d_view(&s3d, 1440.0);
        let runtime = wgal_scene::scene3d_view(&s3d, 1440.0);
        assert_eq!(export, runtime, "双端视图必须一致");

